import type { BankQuestion } from "@/lib/bank";

/** Current Electricity (Physics (JEE/NEET)): 128 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"phy-current-electricity-1","question":"A 2 Ω resistor carries a steady current of 3 A. The power dissipated in it is:","options":["6 W","9 W","18 W","12 W"],"answer":2,"explanation":"P = I²R = 3² × 2 = 18 W. Using P = IR (6 W) or I × R² is the usual slip.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-current-electricity-2","question":"The SI unit of electrical resistivity is:","options":["Ω","Ω/m","Ω·m","Ω·m²"],"answer":2,"explanation":"From R = ρL/A, ρ = RA/L has units Ω·m²/m = Ω·m. Conductivity is measured in S/m (or Ω⁻¹·m⁻¹).","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-current-electricity-3","question":"Kirchhoff's junction (current) rule is a consequence of the conservation of:","options":["Energy","Charge","Momentum","Mass"],"answer":1,"explanation":"Charge cannot pile up at a junction in steady state, so the current entering equals the current leaving: conservation of charge. The loop rule follows from conservation of energy.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"phy-current-electricity-4","question":"A uniform wire of resistance R is stretched so that its length becomes double (volume and resistivity unchanged). Its new resistance is:","options":["2R","4R","R/2","8R"],"answer":1,"explanation":"Doubling the length at constant volume halves the area. R = ρL/A, so R' = ρ(2L)/(A/2) = 4R. In general stretching by a factor n multiplies resistance by n².","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-current-electricity-5","question":"A copper wire of cross-section 1 mm² carries a current of 1.36 A. If the free-electron density of copper is 8.5 × 10²⁸ m⁻³, the drift speed of the electrons is (e = 1.6 × 10⁻¹⁹ C):","options":["10⁻² m/s","10⁻³ m/s","10⁻⁴ m/s","10⁻⁶ m/s"],"answer":2,"explanation":"v_d = I/(neA) = 1.36 / (8.5 × 10²⁸ × 1.6 × 10⁻¹⁹ × 10⁻⁶) = 1.36 / (1.36 × 10⁴) = 10⁻⁴ m/s, i.e. a tenth of a millimetre per second.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-current-electricity-6","question":"Three identical cells, each of emf 2 V and internal resistance 1 Ω, are connected in series across an external resistance of 3 Ω. The current in the circuit is:","options":["0.5 A","1 A","1.5 A","2 A"],"answer":1,"explanation":"Total emf = 3 × 2 = 6 V, total internal resistance = 3 × 1 = 3 Ω. I = 6/(3 + 3) = 1 A. Forgetting the internal resistance gives the wrong 2 A.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-current-electricity-7","question":"The resistance of a wire is 10 Ω at 0 °C. If its temperature coefficient of resistance is 0.004 per °C, its resistance at 50 °C is:","options":["11 Ω","12 Ω","15 Ω","20 Ω"],"answer":1,"explanation":"R_t = R₀(1 + αt) = 10 × (1 + 0.004 × 50) = 10 × 1.2 = 12 Ω.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-current-electricity-8","question":"In a Wheatstone bridge the arms have resistances P = 2 Ω, Q = 4 Ω and R = 3 Ω. For the galvanometer to show zero deflection, the fourth arm S must be:","options":["6 Ω","1.5 Ω","8 Ω","2.67 Ω"],"answer":0,"explanation":"Balance condition P/Q = R/S gives 2/4 = 3/S, so S = 6 Ω. Taking P/Q = S/R gives the wrong 1.5 Ω.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-current-electricity-9","question":"A bulb is rated 100 W, 220 V. Its filament resistance when working at the rated voltage is:","options":["2.2 Ω","48.4 Ω","220 Ω","484 Ω"],"answer":3,"explanation":"P = V²/R, so R = V²/P = 220²/100 = 48400/100 = 484 Ω. (The cold resistance of the filament is much lower.)","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-current-electricity-10","question":"In a potentiometer experiment a cell gives a balance length of 240 cm. When the cell is shunted by a 2 Ω resistor the balance length drops to 120 cm. The internal resistance of the cell is:","options":["1 Ω","0.5 Ω","4 Ω","2 Ω"],"answer":3,"explanation":"r = R(l₁ − l₂)/l₂ = 2 × (240 − 120)/120 = 2 Ω. The emf corresponds to l₁ and the terminal voltage across R to l₂, and E/V = (R + r)/R.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-current-electricity-11","question":"A 60 W bulb and a 100 W bulb, both rated for 220 V, are connected in series across a 220 V supply. Which statement is correct?","options":["The 100 W bulb glows brighter because it is rated higher","Both glow at their rated power","Both glow equally because the current is the same","The 60 W bulb glows brighter because it has the higher resistance"],"answer":3,"explanation":"R = V²/P, so the 60 W bulb has the larger resistance (807 Ω vs 484 Ω). In series the current is common and P = I²R, so the 60 W bulb dissipates more and glows brighter. Neither reaches its rated power because the supply is shared.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-current-electricity-12","question":"A uniform wire of resistance 12 Ω is bent into a circle. The resistance between two points on the circle separated by a quarter of the circumference is:","options":["3 Ω","6 Ω","9 Ω","2.25 Ω"],"answer":3,"explanation":"The two arcs between the points have resistances 3 Ω (one quarter) and 9 Ω (three quarters), in parallel: R = 3 × 9/(3 + 9) = 27/12 = 2.25 Ω. Diametrically opposite points would give 3 Ω.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-current-electricity-13","question":"A cell of emf 12 V and internal resistance 2 Ω is connected to a variable external resistor. The maximum power that can be delivered to the external resistor is:","options":["72 W","36 W","18 W","9 W"],"answer":2,"explanation":"Power in R is maximum when R = r (maximum power transfer theorem): P_max = E²/(4r) = 144/8 = 18 W. At that setting the efficiency is only 50%.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-current-electricity-14","question":"In a metre bridge a 6 Ω resistor is in the left gap and an unknown resistance S in the right gap; the null point is at 40 cm from the left end. The value of S is:","options":["4 Ω","2.4 Ω","15 Ω","9 Ω"],"answer":3,"explanation":"R/S = l/(100 − l) gives 6/S = 40/60, so S = 9 Ω. If the two resistors are interchanged the null point shifts to 60 cm from the left end.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-current-electricity-15","question":"Two cells, one of emf 3 V and internal resistance 1 Ω and the other of emf 6 V and internal resistance 2 Ω, are connected in parallel with like terminals together. The emf of the equivalent single cell is:","options":["4 V","4.5 V","3 V","9 V"],"answer":0,"explanation":"E_eq = (E₁r₂ + E₂r₁)/(r₁ + r₂) = (3 × 2 + 6 × 1)/(1 + 2) = 12/3 = 4 V, with r_eq = r₁r₂/(r₁ + r₂) = 2/3 Ω. The simple average 4.5 V is wrong because the cells have different internal resistances.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-16","question":"A cell of emf 6 V and internal resistance 0.5 Ω is being charged by a current of 2 A. The potential difference across its terminals during charging is:","options":["5 V","6 V","4 V","7 V"],"answer":3,"explanation":"While charging, the current is forced in against the emf, so V = E + Ir = 6 + 2 × 0.5 = 7 V. During discharge the terminal voltage would be E − Ir = 5 V.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-current-electricity-17","question":"A galvanometer of resistance 100 Ω gives full-scale deflection for a current of 10 mA. The resistance to be connected in series to convert it into a voltmeter reading up to 10 V is:","options":["900 Ω","1000 Ω","100 Ω","1100 Ω"],"answer":0,"explanation":"R = V/I_g − G = 10/0.01 − 100 = 1000 − 100 = 900 Ω. Forgetting to subtract G gives 1000 Ω.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-current-electricity-18","question":"An immersion heater rated 1 kW is used to heat 1 kg of water from 20 °C to 100 °C. Neglecting heat loss and taking the specific heat of water as 4200 J/(kg·°C), the time required is:","options":["84 s","168 s","420 s","336 s"],"answer":3,"explanation":"Heat needed Q = mcΔT = 1 × 4200 × 80 = 336000 J. Time = Q/P = 336000/1000 = 336 s, about 5.6 minutes.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-current-electricity-19","question":"How many of the following statements are correct? (A) The drift speed of electrons in a typical household wire is of the order of 10⁻⁴ m/s. (B) The resistivity of a semiconductor decreases with rise in temperature. (C) Ohm's law is a fundamental law of nature obeyed by all conductors. (D) Manganin is used for standard resistances because its temperature coefficient of resistance is very small.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(A), (B) and (D) are correct. (C) is wrong: Ohm's law is an empirical relation obeyed only by ohmic conductors; diodes, electrolytes and gas discharge tubes violate it.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-current-electricity-20","question":"A cell delivers a current of 1 A through an external resistance of 4 Ω and 0.5 A through an external resistance of 9 Ω. The emf and internal resistance of the cell are:","options":["5 V, 1 Ω","4 V, 0 Ω","6 V, 2 Ω","4.5 V, 0.5 Ω"],"answer":0,"explanation":"E = I(R + r): 1 × (4 + r) = 0.5 × (9 + r) gives 4 + r = 4.5 + 0.5r, so r = 1 Ω and E = 5 V. Check: 5/(9 + 1) = 0.5 A.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-current-electricity-21","question":"Two cells, 12 V (internal resistance 2 Ω) and 6 V (internal resistance 2 Ω), are connected in parallel with like terminals joined, and the combination is connected to a 1 Ω external resistor. The current supplied by the 6 V cell is:","options":["0.75 A","1.5 A","3.75 A","Zero"],"answer":0,"explanation":"Equivalent cell: E = (12 × 2 + 6 × 2)/4 = 9 V, r = 1 Ω. Total current = 9/(1 + 1) = 4.5 A and terminal voltage = 4.5 × 1 = 4.5 V. Since 4.5 V < 6 V the 6 V cell still discharges: I₂ = (6 − 4.5)/2 = 0.75 A; the 12 V cell gives (12 − 4.5)/2 = 3.75 A, and 0.75 + 3.75 = 4.5 A.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-current-electricity-22","question":"An infinite ladder network is built from resistors R, with R in each series arm and R in each shunt arm. The equivalent resistance between the input terminals is:","options":["2R","R(1 + √5)/2","R(√5 − 1)/2","R√2"],"answer":1,"explanation":"Let the equivalent resistance be x. Removing the first section leaves the same infinite ladder, so x = R + (R·x)/(R + x). This gives x² − Rx − R² = 0, hence x = R(1 + √5)/2 ≈ 1.62 R (the negative root is rejected).","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-23","question":"A potentiometer wire of length 1 m and resistance 10 Ω is connected in series with a 30 Ω resistor and a driver cell of emf 2 V and negligible internal resistance. A cell of emf 0.2 V is balanced against this wire. The balance length is:","options":["10 cm","20 cm","40 cm","80 cm"],"answer":2,"explanation":"Current in the wire = 2/(10 + 30) = 0.05 A, so the potential drop across the 1 m wire is 0.05 × 10 = 0.5 V, i.e. a gradient of 0.5 V/m. Balance length = 0.2/0.5 = 0.4 m = 40 cm.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-current-electricity-24","question":"Resistors of 2 Ω and 8 Ω, when connected one at a time across the same cell, dissipate equal power. The internal resistance of the cell is:","options":["5 Ω","4 Ω","6 Ω","16 Ω"],"answer":1,"explanation":"P = E²R/(R + r)². Equal power for R₁ and R₂ requires R₁(R₂ + r)² = R₂(R₁ + r)², which simplifies to r² = R₁R₂. So r = √(2 × 8) = 4 Ω (the geometric mean, not the arithmetic mean 5 Ω).","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-25","question":"Assertion (A): In a metre-bridge experiment the null point is unchanged when the positions of the cell and the galvanometer are interchanged. Reason (R): The balance condition of a Wheatstone bridge does not depend on which diagonal carries the cell and which carries the galvanometer.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"At balance P/Q = R/S, a relation among the four arm resistances only. Swapping the cell and the galvanometer between the two diagonals leaves the condition, and hence the null point, unchanged. R is exactly why A holds.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-current-electricity-26","question":"Match the application (List I) with the material and the property that makes it suitable (List II). List I: (P) heating element of an electric iron; (Q) fuse wire; (R) standard resistance coil; (S) household connecting wire. List II: (1) copper – low resistivity; (2) nichrome – high resistivity and high melting point; (3) manganin – very small temperature coefficient; (4) tin–lead alloy – low melting point.","options":["P-2, Q-4, R-3, S-1","P-2, Q-3, R-4, S-1","P-3, Q-4, R-2, S-1","P-4, Q-2, R-3, S-1"],"answer":0,"explanation":"Nichrome resists oxidation and stays solid while red hot, so it is the heating element; a fuse must melt early, so a low-melting tin–lead alloy; standard resistances must not drift with temperature, so manganin; connecting wires should waste little energy, so copper.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-current-electricity-27","question":"A copper resistor (temperature coefficient +0.004 per °C) of 10 Ω is to be joined in series with a carbon resistor (temperature coefficient −0.0005 per °C) so that the total resistance does not change with temperature. The carbon resistor required is:","options":["10 Ω","1.25 Ω","80 Ω","40 Ω"],"answer":2,"explanation":"For the sum to be temperature-independent, R_Cu α_Cu + R_C α_C = 0: 10 × 0.004 = R_C × 0.0005, so R_C = 0.04/0.0005 = 80 Ω. The rise in the copper resistance is then exactly cancelled by the fall in the carbon resistance.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-28","question":"A tapered copper wire has diameter 2 mm at end P and 1 mm at end Q and carries a steady current. The ratio of the drift speed of electrons at Q to that at P is:","options":["2 : 1","4 : 1","1 : 2","1 : 4"],"answer":1,"explanation":"The current is the same at every cross-section, so I = neAv_d gives v_d ∝ 1/A ∝ 1/d². With d_P/d_Q = 2, v_Q/v_P = (2)² = 4 : 1. The electric field inside the wire is also 4 times larger at Q.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-current-electricity-29","question":"An electric kettle has two heating coils. Used alone on the same supply, coil A boils a given amount of water in 10 minutes and coil B in 15 minutes. If the two coils are connected in parallel across the same supply, the water boils in:","options":["25 min","12.5 min","6 min","5 min"],"answer":2,"explanation":"At fixed voltage, power ∝ 1/R, and the heat required is fixed, so t ∝ R. In parallel 1/R = 1/R_A + 1/R_B, hence 1/t = 1/10 + 1/15 = 1/6, giving t = 6 min. In series the time would be 10 + 15 = 25 min.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-current-electricity-30","question":"A 12 V battery of negligible internal resistance is connected to a 2 Ω resistor and a 4 Ω resistor in series. A 3 μF capacitor is connected across the 4 Ω resistor. In the steady state the charge on the capacitor is:","options":["12 μC","24 μC","36 μC","8 μC"],"answer":1,"explanation":"In steady state no current flows through the capacitor branch, so the resistors carry I = 12/(2 + 4) = 2 A and the potential difference across the 4 Ω resistor is 8 V. Q = CV = 3 μF × 8 V = 24 μC. Using the full 12 V gives the wrong 36 μC.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-current-electricity-31","question":"A current of 3 A flows through a 4 Ω resistor. The potential difference across it is:","options":["7 V","0.75 V","12 V","1.33 V"],"answer":2,"explanation":"By Ohm's law V = IR = 3 × 4 = 12 V.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-current-electricity-32","question":"A carbon resistor has colour bands brown, black, red and gold, in that order. Its resistance is:","options":["100 Ω ± 10%","10 Ω ± 5%","1 kΩ ± 5%","102 Ω ± 5%"],"answer":2,"explanation":"Brown = 1, black = 0, red = multiplier 10², gold = ±5%: 10 × 100 = 1000 Ω ± 5%.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-current-electricity-33","question":"A 4 Ω resistor is connected in series with a parallel combination of 6 Ω and 3 Ω across a 12 V battery of negligible internal resistance. The current through the 3 Ω resistor is:","options":["1 A","2 A","4/3 A","2/3 A"],"answer":2,"explanation":"6 ∥ 3 = 2 Ω; total 6 Ω, so the battery current is 2 A and the voltage across the parallel part is 4 V. Current in 3 Ω = 4/3 A.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-current-electricity-34","question":"A cell of emf 1.5 V and internal resistance 0.5 Ω is connected to a 2.5 Ω resistor. The terminal potential difference of the cell is:","options":["0.25 V","1.0 V","1.5 V","1.25 V"],"answer":3,"explanation":"I = 1.5/(2.5 + 0.5) = 0.5 A; V = E − Ir = 1.5 − 0.25 = 1.25 V. The 0.25 V is the drop inside the cell.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-current-electricity-35","question":"Twelve identical resistors, each R, form the edges of a cube. The equivalent resistance between two diagonally opposite corners of the cube is:","options":["7R/12","R/2","5R/6","3R/4"],"answer":2,"explanation":"By symmetry the current I splits 3 ways (I/3), then 6 ways (I/6), then joins 3 ways (I/3). V = R(I/3 + I/6 + I/3) = 5IR/6.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-36","question":"In a potentiometer, a standard cell of emf 1.5 V balances at 300 cm of the wire. Another cell balances at 400 cm of the same wire. The emf of the second cell is:","options":["1.5 V","1.125 V","2.5 V","2 V"],"answer":3,"explanation":"At balance E ∝ l: E₂ = 1.5 × 400/300 = 2 V. Inverting the ratio gives 1.125 V.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-current-electricity-37","question":"A galvanometer of resistance 50 Ω gives full-scale deflection at 5 mA. The resistance of the shunt needed to convert it into an ammeter of range 0–5 A is about:","options":["0.05 Ω","5 Ω","0.5 Ω","0.005 Ω"],"answer":0,"explanation":"S = I_g G/(I − I_g) = 0.005 × 50/4.995 ≈ 0.05 Ω, connected in parallel. A large series resistance would instead make a voltmeter.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-current-electricity-38","question":"Twelve identical cells, each of emf 2 V and internal resistance 0.5 Ω, are arranged in a mixed grouping to send the maximum current through an external resistance of 1.5 Ω. That maximum current is:","options":["4 A","6 A","2 A","3 A"],"answer":0,"explanation":"With n in series per row and m rows (nm = 12), the current is greatest when nr/m = R: 0.5n/m = 1.5 → n = 3m → m = 2, n = 6. I = nE/(R + nr/m) = 12/(1.5 + 1.5) = 4 A.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-39","question":"A 10 μF capacitor is charged through a 100 kΩ resistor from a battery. The time taken for its charge to reach half of its final value is about:","options":["0.69 s","0.5 s","1 s","1.39 s"],"answer":0,"explanation":"τ = RC = 10⁵ × 10⁻⁵ = 1 s. q = q₀(1 − e^(−t/τ)) = q₀/2 gives t = τ ln 2 ≈ 0.69 s. In one time constant the charge reaches 63%, not 50%.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-40","question":"A 10 V battery of negligible internal resistance is connected across two parallel branches: branch 1 has 2 Ω followed by 3 Ω, branch 2 has 3 Ω followed by 2 Ω (both starting from the positive terminal). A 2 μF capacitor is connected between the junction points of the two branches. In the steady state the charge on the capacitor is:","options":["8 μC","4 μC","zero","12 μC"],"answer":1,"explanation":"Each branch carries 2 A. The junction of branch 1 is 10 − 2 × 2 = 6 V above the negative terminal; that of branch 2 is 10 − 2 × 3 = 4 V. The capacitor has 2 V across it, so Q = 2 × 2 = 4 μC. It would be zero only if the bridge were balanced.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-41","question":"How many of the following statements are correct?\n(A) The resistivity of a metal increases with temperature.\n(B) The resistivity of a semiconductor decreases with temperature.\n(C) Manganin is used in standard resistors because of its high temperature coefficient of resistance.\n(D) The resistance of a wire depends on its length and cross-section, but its resistivity does not.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"A, B and D are correct. C is wrong: manganin and constantan are chosen precisely because their temperature coefficient is very small. So only three are correct.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-current-electricity-42","question":"Resistors of 3 Ω and 6 Ω in parallel are connected in series with a 4 Ω resistor across a battery. The ratio of the heat produced per second in the 3 Ω, 6 Ω and 4 Ω resistors is:","options":["6 : 3 : 2","2 : 1 : 6","2 : 1 : 3","1 : 2 : 6"],"answer":1,"explanation":"If I flows through the 4 Ω, the 3 Ω takes 2I/3 and the 6 Ω takes I/3. Powers: 3(4I²/9) = 4I²/3, 6(I²/9) = 2I²/3 and 4I². Ratio = 4/3 : 2/3 : 4 = 2 : 1 : 6.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-43","question":"The potential difference across a metal wire is doubled and, at the same time, the wire is replaced by one of the same material and cross-section but twice the length. The drift speed of the electrons:","options":["remains the same","halves","becomes four times","doubles"],"answer":0,"explanation":"v_d = eEτ/m depends on the field E = V/L. Doubling both V and L leaves E, and hence v_d, unchanged, even though the current is the same too.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-current-electricity-44","question":"Two 10 kΩ resistors are connected in series across a 10 V supply of negligible internal resistance. A voltmeter of resistance 10 kΩ is connected across one of them. Its reading is:","options":["6.67 V","5 V","2.5 V","3.33 V"],"answer":3,"explanation":"The voltmeter in parallel with 10 kΩ gives 5 kΩ, in series with the other 10 kΩ: V = 10 × 5/15 ≈ 3.33 V. 5 V is the reading of an ideal (infinite-resistance) voltmeter.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-45","question":"Assertion (A): A potentiometer is preferred to a voltmeter for measuring the emf of a cell.\nReason (R): At the balance point, the potentiometer draws no current from the cell.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A: a voltmeter draws some current and so reads the terminal voltage E − Ir, while a potentiometer at balance draws none and measures the emf itself.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "phy-current-electricity-46", "question": "The reciprocal of resistance is called conductance. Its SI unit is the:", "options": ["ohm-metre", "henry", "siemens", "weber"], "answer": 2, "explanation": "Conductance G = 1/R is measured in siemens (S), formerly called the mho (Ω⁻¹). The ohm-metre is the unit of resistivity.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-current-electricity-47", "question": "A 1 kW electric heater is used for 2 hours. The electrical energy it consumes is:", "options": ["7.2 × 10⁶ J", "2 × 10³ J", "7.2 × 10³ J", "3.6 × 10⁶ J"], "answer": 0, "explanation": "E = Pt = 1 kW × 2 h = 2 kWh = 2 × 3.6 × 10⁶ J = 7.2 × 10⁶ J. 3.6 × 10⁶ J is a single kWh.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-current-electricity-48", "question": "Five resistors of 10 Ω each are first all connected in series and then all in parallel. The ratio of the maximum to the minimum equivalent resistance is:", "options": ["5", "10", "50", "25"], "answer": 3, "explanation": "Series: 5 × 10 = 50 Ω; parallel: 10/5 = 2 Ω. The ratio is 50/2 = 25 = n².", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-current-electricity-49", "question": "A current of 2 A flows through a wire of cross-sectional area 1 mm². The current density in the wire is:", "options": ["2 A/m²", "2 × 10⁶ A/m²", "2 × 10³ A/m²", "2 × 10⁻⁶ A/m²"], "answer": 1, "explanation": "J = I/A = 2/(1 × 10⁻⁶) = 2 × 10⁶ A/m², since 1 mm² = 10⁻⁶ m² (not 10⁻³ m²).", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-current-electricity-50", "question": "The electron mobility in a conductor is 4 × 10⁻³ m²/(V s). In an electric field of 0.5 V/m, the drift speed of the electrons is:", "options": ["8 × 10⁻³ m/s", "2 × 10⁻³ m/s", "1.25 × 10⁻⁴ m/s", "2 × 10⁻² m/s"], "answer": 1, "explanation": "Mobility is drift speed per unit field: v_d = μE = 4 × 10⁻³ × 0.5 = 2 × 10⁻³ m/s.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "phy-current-electricity-51", "question": "Two bulbs rated 25 W, 220 V and 100 W, 220 V are connected in parallel across a 220 V supply. Which statement is correct?", "options": ["The 25 W bulb glows brighter", "Both glow equally", "Neither glows at its rated power", "The 100 W bulb glows brighter"], "answer": 3, "explanation": "In parallel each bulb gets its rated 220 V and so dissipates its rated power: the 100 W bulb is brighter. In series the order reverses, because the 25 W bulb has the larger resistance.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-current-electricity-52", "question": "Three resistors of 6 Ω each are connected to form a triangle. The resistance between any two corners of the triangle is:", "options": ["4 Ω", "2 Ω", "18 Ω", "9 Ω"], "answer": 0, "explanation": "Between two corners, one 6 Ω side is in parallel with the other two sides in series (12 Ω): 6 × 12/18 = 4 Ω.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "phy-current-electricity-53", "question": "A wire is stretched so that its length increases by 10%, its volume remaining constant. Its resistance increases by:", "options": ["10%", "20%", "21%", "11%"], "answer": 2, "explanation": "At constant volume A ∝ 1/L, so R ∝ L². (1.1)² = 1.21, an increase of 21%. 20% is the small-change approximation 2 × 10%, which is not exact for 10%.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "phy-current-electricity-54", "question": "Three identical bulbs are connected to a supply as follows: two of them in parallel, and this pair in series with the third. The ratio of the power of the series bulb to that of one bulb in the parallel pair is:", "options": ["2 : 1", "1 : 2", "1 : 4", "4 : 1"], "answer": 3, "explanation": "The series bulb carries the full current I, and each parallel bulb carries I/2. With equal resistances P ∝ I², so the ratio is 1 : (1/4) = 4 : 1.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-current-electricity-55", "question": "Two wires of the same material have lengths l and 2l and radii r and 2r. They are connected in parallel across a battery. The ratio of the heat produced in them per second (first : second) is:", "options": ["2 : 1", "1 : 2", "1 : 4", "4 : 1"], "answer": 1, "explanation": "R₂ = ρ(2l)/(π4r²) = R₁/2. In parallel the voltage is common, so H = V²/R and H₁ : H₂ = R₂ : R₁ = 1 : 2.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-current-electricity-56", "question": "A wire has a resistance of 5 Ω at 50 °C and 6 Ω at 100 °C. Taking R = R₀(1 + αt), its resistance at 0 °C is:", "options": ["4.5 Ω", "3 Ω", "4 Ω", "4.17 Ω"], "answer": 2, "explanation": "6/5 = (1 + 100α)/(1 + 50α), so 6 + 300α = 5 + 500α, giving α = 0.005 per °C, and R₀ = 5/1.25 = 4 Ω. Extrapolating the straight line 1 Ω per 50 °C back to 0 °C gives the same 4 Ω.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-current-electricity-57", "question": "n identical cells, each of emf E and internal resistance r, send the same current through an external resistor R whether they are all connected in series or all in parallel. Then R equals:", "options": ["r", "nr", "r/n", "n²r"], "answer": 0, "explanation": "Series: nE/(R + nr); parallel: E/(R + r/n) = nE/(nR + r). Equal when R + nr = nR + r, i.e. (n − 1)R = (n − 1)r, so R = r.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "phy-current-electricity-58", "question": "The colour code of a carbon resistor of 4.7 kΩ ± 5% is:", "options": ["yellow, violet, orange, gold", "violet, yellow, red, silver", "yellow, violet, red, gold", "yellow, violet, red, silver"], "answer": 2, "explanation": "4.7 kΩ = 47 × 10² Ω: yellow (4), violet (7), red (multiplier 10²), and gold for ±5%. Orange would mean 47 kΩ, and silver means ±10%.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "phy-current-electricity-59", "question": "A galvanometer is shunted by a resistance equal to one-ninth of its own resistance. The fraction of the total current that passes through the galvanometer is:", "options": ["1/10", "1/9", "9/10", "8/9"], "answer": 0, "explanation": "In parallel the current divides inversely to resistance: I_g/I = S/(G + S) = (G/9)/(10G/9) = 1/10. 1/9 is the ratio of the two currents, not the fraction of the total.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "phy-current-electricity-60", "question": "How many of the following statements are correct?\n(A) Kirchhoff's loop rule is a consequence of the conservation of energy.\n(B) The current is the same through all resistors connected in series.\n(C) The internal resistance of a dry cell increases as it ages.\n(D) The terminal voltage of a cell is always less than its emf.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A, B and C are correct. D is wrong: while a cell is being charged its terminal voltage is E + Ir, which is greater than its emf. Three are correct.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-current-electricity-61", "question": "In a network, the resistances are AB = 1 Ω, BC = 2 Ω, AD = 2 Ω, DC = 1 Ω, and a 1 Ω resistor joins B and D. The equivalent resistance between A and C is:", "options": ["1.5 Ω", "1.2 Ω", "2 Ω", "1.4 Ω"], "answer": 3, "explanation": "The bridge is unbalanced. With V_A = 1 V and V_C = 0, Kirchhoff's rules give V_B = 4/7 V and V_D = 3/7 V; the current from A is 3/7 + 2/7 = 5/7 A, so R = 7/5 = 1.4 Ω. 1.5 Ω wrongly ignores the BD resistor.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "phy-current-electricity-62", "question": "An uncharged 10 μF capacitor is charged through a resistor from a 100 V battery until fully charged. The heat dissipated in the resistor:", "options": ["is 0.1 J, whatever the value of the resistance", "is 0.05 J, whatever the value of the resistance", "is 0.05 J only if the resistance is small", "is zero if the resistance is very small"], "answer": 1, "explanation": "The battery supplies QV = (10⁻³ C)(100 V) = 0.1 J, the capacitor stores ½CV² = 0.05 J, and the other 0.05 J is always lost as heat. The resistance only changes how fast this happens.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-current-electricity-63", "question": "Bulbs rated 100 W, 220 V and 25 W, 220 V are connected in series across a 440 V supply. What happens?", "options": ["The 100 W bulb fuses and then both go out", "The 25 W bulb fuses and then both go out", "Both glow normally at their rated power", "Both glow dimly but neither fuses"], "answer": 1, "explanation": "R = V²/P: 484 Ω and 1936 Ω. Current = 440/2420 ≈ 0.18 A, so the 25 W bulb gets 0.18 × 1936 ≈ 352 V, well above 220 V, and fuses; the 100 W bulb gets only 88 V. The series circuit then breaks, so both go out.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-current-electricity-64", "question": "Twelve identical resistors, each R, form the edges of a cube. The equivalent resistance between two corners joined by one edge is:", "options": ["5R/6", "3R/4", "R/2", "7R/12"], "answer": 3, "explanation": "By symmetry (or by Kirchhoff's rules), between adjacent corners R_eq = 7R/12. 5R/6 is the result for opposite corners along a body diagonal, and 3R/4 for corners across a face diagonal.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "phy-current-electricity-65", "question": "To measure a resistance R, a voltmeter of resistance 1000 Ω is connected directly across R, and an ammeter in the main line reads the total current. The voltmeter reads 10 V and the ammeter 0.1 A. The true value of R is about:", "options": ["111 Ω", "100 Ω", "90 Ω", "1100 Ω"], "answer": 0, "explanation": "The ammeter also counts the voltmeter's current, 10/1000 = 0.01 A. So the current through R is 0.09 A and R = 10/0.09 ≈ 111 Ω. 100 Ω is V/I, which ignores the voltmeter's current.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-current-electricity-66", "question": "Assertion (A): The electric field inside a wire carrying a steady current is zero.\nReason (R): The free electrons in the wire drift under the action of an electric field inside it.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 3, "explanation": "A is false: the zero-field rule holds only for conductors in electrostatic equilibrium. A current-carrying wire has a field E = V/L along it, and R correctly says this field is what drives the drift.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-current-electricity-67", "question": "Match the combination (List I) with its equivalent resistance (List II).\nList I: (P) 3 Ω and 6 Ω in parallel; (Q) two 8 Ω resistors in series, together in parallel with 16 Ω; (R) a uniform 12 Ω wire bent into a circle, measured across a diameter; (S) three 3 Ω resistors in parallel.\nList II: (1) 1 Ω; (2) 2 Ω; (3) 3 Ω; (4) 8 Ω.", "options": ["P-2, Q-3, R-4, S-1", "P-1, Q-4, R-3, S-2", "P-2, Q-4, R-3, S-1", "P-3, Q-4, R-2, S-1"], "answer": 2, "explanation": "P: 18/9 = 2 Ω. Q: 16 ∥ 16 = 8 Ω. R: two 6 Ω halves in parallel = 3 Ω. S: 3/3 = 1 Ω. So P-2, Q-4, R-3, S-1.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-current-electricity-68", "question": "A fuse wire of radius r melts at a current of 5 A. Assuming heat is lost only from its surface, at a rate proportional to the surface area, a wire of the same material and radius 4r will melt at a current of:", "options": ["20 A", "80 A", "10 A", "40 A"], "answer": 3, "explanation": "At the melting point I²ρl/(πr²) ∝ 2πrl, so I² ∝ r³ and I ∝ r^(3/2). 4^(3/2) = 8, so I = 8 × 5 = 40 A. 80 A assumes I ∝ r², the cross-section.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-current-electricity-69", "question": "Ten identical cells, each of emf 1.5 V and internal resistance 0.5 Ω, are meant to be joined in series, but two of them are connected the wrong way round. The battery is connected to an external 4 Ω resistor. The current is:", "options": ["1.67 A", "1 A", "0.67 A", "1.33 A"], "answer": 1, "explanation": "Each reversed cell cancels one correct cell: emf = (10 − 2 × 2) × 1.5 = 9 V, while all ten internal resistances still add to 5 Ω. I = 9/(5 + 4) = 1 A. 1.67 A ignores the reversed cells (15/9 A).", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-current-electricity-70", "question": "A power of 10 kW is transmitted through a line of total resistance 1 Ω. The power lost in the line when the power is sent at 250 V, and when it is sent at 1000 V, is respectively:", "options": ["400 W and 100 W", "1600 W and 400 W", "1600 W and 100 W", "800 W and 200 W"], "answer": 2, "explanation": "I = P/V gives 40 A and 10 A; loss = I²R gives 1600 W and 100 W. Raising the voltage 4 times cuts the loss 16 times. 1600 W and 400 W assumes the loss falls only in proportion to the voltage.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id":"phy-current-electricity-71","question":"Six identical resistors, each R, form the sides of a regular hexagon (no diagonals). The equivalent resistance between two opposite vertices is:","options":["1.5R","5R/6","3R","R"],"answer":0,"explanation":"Between opposite vertices there are two paths of three resistors each: 3R ∥ 3R = 1.5R. 5R/6 is the answer for two adjacent vertices.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-72","question":"By mistake, a student connects a good voltmeter in series with a 10 Ω resistor and an ammeter across a 6 V cell of small internal resistance. What do the meters show?","options":["The ammeter reads about 0.6 A and the voltmeter about 6 V","The ammeter reads nearly zero and the voltmeter nearly 6 V","The ammeter reads nearly zero and so does the voltmeter","The ammeter burns out because the voltmeter has low resistance"],"answer":1,"explanation":"A voltmeter has a very large resistance, so in series it makes the current nearly zero; almost no voltage drops across the 10 Ω resistor and the ammeter, so the voltmeter reads nearly the full emf, about 6 V.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-73","question":"A battery of emf E and internal resistance r is connected to a variable load resistor. When the load is adjusted so that it receives the maximum possible power, the efficiency of power transfer (power in load / power produced by the battery) is:","options":["100%","75%","50%","25%"],"answer":2,"explanation":"Maximum power is delivered when R = r. The same current flows through R and r, so equal power is wasted inside the battery: efficiency = R/(R + r) = 50%. Higher efficiency needs R > r, but then the power in the load is less than the maximum.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-74","question":"For a cell, the terminal voltage is 1.5 V when no current is drawn and 1.2 V when it delivers 0.6 A. If its terminals are short-circuited by a thick wire of negligible resistance, the current will be about:","options":["2.0 A","2.4 A","6.0 A","3.0 A"],"answer":3,"explanation":"E = 1.5 V and r = (1.5 − 1.2)/0.6 = 0.5 Ω, so the short-circuit current is E/r = 1.5/0.5 = 3.0 A. 2.4 A (= 1.2/0.5) wrongly uses the terminal voltage at 0.6 A as the driving emf.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-75","question":"A 20 Ω rheostat is connected across a 12 V battery of negligible internal resistance and used as a potential divider, with the slider at its midpoint. A 10 Ω load is connected between the slider and the negative end of the rheostat. The voltage across the load is:","options":["4 V","3 V","8 V","6 V"],"answer":0,"explanation":"The lower half (10 Ω) is in parallel with the 10 Ω load, giving 5 Ω, in series with the upper 10 Ω. V_load = 12 × 5/15 = 4 V. 6 V is the unloaded value; connecting a load always pulls the divider output down.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-76","question":"Two cells, of emf 12 V (internal resistance 2 Ω) and 6 V (internal resistance 3 Ω), have their positive terminals joined at A and their negative terminals joined at B, and a 6 Ω resistor is also connected between A and B. The current through the 6 V cell is:","options":["2/3 A, flowing out of its positive terminal","2/3 A, flowing into its positive terminal (the cell is being charged)","2 A, flowing out of its positive terminal","zero"],"answer":1,"explanation":"V_AB = (12/2 + 6/3 + 0/6)/(1/2 + 1/3 + 1/6) = 8 V. In the 6 V branch, I = (6 − 8)/3 = −2/3 A, i.e. 2/3 A is driven into its positive terminal, so this cell is being charged. Assuming every cell must discharge gives the wrong direction.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-77","question":"A potentiometer wire 10 m long has a resistance of 4 Ω. It is driven by a cell of emf 2 V and internal resistance 1 Ω through a series resistor. For a potential gradient of 1 mV/cm along the wire, the series resistor must be:","options":["4 Ω","5 Ω","3 Ω","8 Ω"],"answer":2,"explanation":"1 mV/cm = 0.1 V/m, so the wire must carry 0.1 × 10/4 = 0.25 A. Total resistance = 2/0.25 = 8 Ω = 4 (wire) + 1 (cell) + R, so R = 3 Ω. Forgetting the internal resistance gives 4 Ω.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-78","question":"The current through a 5 Ω resistor rises uniformly from 0 to 10 A in 4 s. The heat produced in the resistor during this time is about:","options":["500 J","1000 J","2000 J","667 J"],"answer":3,"explanation":"i = 2.5t, so H = ∫ i²R dt = 5 × 6.25 × ∫₀⁴ t² dt = 31.25 × 64/3 ≈ 667 J. Using the average current 5 A gives 500 J, but heat depends on the mean of i², not the square of the mean of i.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-79","question":"A wire of uniform cross-section has resistivity that increases linearly along its length, from ρ₀ at end P to 2ρ₀ at end Q. End P is held at potential V and end Q at zero. The potential at the midpoint of the wire is:","options":["7V/12","2V/3","5V/12","V/2"],"answer":0,"explanation":"Resistance from P to x is ∝ ∫₀ˣ (1 + x/L) dx. The whole wire gives 3L/2 and the first half gives L/2 + L/8 = 5L/8, i.e. 5/12 of the total. So the drop from P to the midpoint is 5V/12 and V_mid = 7V/12. 5V/12 is the drop, not the potential.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-80","question":"A 12 V battery of negligible internal resistance is connected through a switch to a 4 Ω resistor in series with a parallel combination of two branches: one is a 4 Ω resistor, the other a 4 Ω resistor in series with an uncharged capacitor. The battery current just after the switch is closed and a long time later are respectively:","options":["1.5 A and 2 A","2 A and 1.5 A","3 A and 1.5 A","2 A and 1 A"],"answer":1,"explanation":"At t = 0 the uncharged capacitor acts as a short, so the two 4 Ω branches are in parallel (2 Ω): I = 12/6 = 2 A. In the steady state the capacitor branch carries no current: I = 12/8 = 1.5 A. Swapping the two limits is the usual slip.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-81","question":"The space between the plates of a charged, isolated parallel-plate capacitor is filled with a slightly conducting dielectric of dielectric constant 5 and resistivity 1 × 10¹¹ Ω m. The time in which the charge on the plates falls to 1/e of its initial value is about (ε₀ = 8.85 × 10⁻¹² F/m):","options":["0.89 s","22 s","4.4 s","it cannot be found without the plate area and separation"],"answer":2,"explanation":"C = Kε₀A/d and the leakage resistance R = ρd/A, so τ = RC = Kε₀ρ: the geometry cancels. τ = 5 × 8.85 × 10⁻¹² × 10¹¹ ≈ 4.4 s. Leaving out K gives 0.89 s.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-82","question":"An infinite square grid is made of identical resistors R, each joining two neighbouring nodes. The equivalent resistance between two adjacent nodes is:","options":["R","R/4","2R/3","R/2"],"answer":3,"explanation":"Feed current I into node A: by symmetry I/4 flows through each of its four resistors, so I/4 goes directly along AB. Draw I out of B (to infinity): another I/4 flows along AB. Superposing, AB carries I/2 when I enters at A and leaves at B, so V_AB = (I/2)R and R_eq = R/2.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-83","question":"A battery is connected through a switch to a 6 kΩ resistor in series with a parallel combination of a 3 kΩ resistor and an uncharged 5 μF capacitor. After the switch is closed, the capacitor voltage rises with a time constant of:","options":["10 ms","30 ms","15 ms","45 ms"],"answer":0,"explanation":"Seen from the capacitor, the battery and resistors form a Thevenin source of resistance 6 kΩ ∥ 3 kΩ = 2 kΩ, so τ = 2 kΩ × 5 μF = 10 ms. Using 6 kΩ alone (30 ms) or 9 kΩ (45 ms) ignores the discharge path through the 3 kΩ.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-84","question":"In a bridge circuit, AB = 10 Ω, BC = 20 Ω, AD = 20 Ω, DC = 10 Ω and a galvanometer of resistance 10 Ω is connected between B and D. A 7 V battery of negligible internal resistance is connected across A and C (A positive). The current through the galvanometer is:","options":["zero, because the bridge is balanced","0.1 A from B to D","0.1 A from D to B","0.2 A from B to D"],"answer":1,"explanation":"The bridge is not balanced (10/20 ≠ 20/10). Node equations: 0.25V_B − 0.1V_D = 0.7 and 0.25V_D − 0.1V_B = 0.35 give V_B = 4 V and V_D = 3 V, so 0.1 A flows from B to D. Checking balance with the wrong pairing of arms leads to 'zero'.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-85","question":"How many of the following statements about conduction in a metal wire are correct?\n(A) The drift speed is v_d = eEτ/m, where τ is the mean time between collisions.\n(B) Mobility is drift speed per unit electric field; its SI unit is m² V⁻¹ s⁻¹.\n(C) For a steady current, the drift speed is greater where the wire is thinner.\n(D) For the same current, a wire of a metal with twice the free-electron density has twice the drift speed.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"A, B and C are correct (C: I = neAv_d with I and n fixed, so v_d ∝ 1/A). D is wrong: v_d = I/(neA), so doubling n halves the drift speed.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-86","question":"Assertion (A): When a metal wire is heated while the potential difference across it is kept fixed, the drift speed of its free electrons decreases.\nReason (R): The mean time between collisions of the electrons with the lattice decreases as the temperature rises.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"With V fixed, E = V/L is fixed and v_d = eEτ/m. Stronger lattice vibrations at higher temperature shorten τ, so v_d (and the current) fall; this is also why the resistivity of a metal rises with temperature. R explains A.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-87","question":"A galvanometer of resistance 100 Ω gives full-scale deflection at 1 mA. Match the conversion (List I) with the resistor needed (List II).\nList I: (P) ammeter of range 1 A; (Q) voltmeter of range 10 V; (R) ammeter of range 10 mA; (S) voltmeter of range 1 V.\nList II: (1) 900 Ω in series; (2) about 11.1 Ω in parallel; (3) 9900 Ω in series; (4) about 0.1 Ω in parallel.","options":["P-2, Q-3, R-4, S-1","P-4, Q-1, R-2, S-3","P-4, Q-3, R-2, S-1","P-2, Q-1, R-4, S-3"],"answer":2,"explanation":"Shunt S = I_gG/(I − I_g): for 1 A, 0.1/0.999 ≈ 0.1 Ω; for 10 mA, 0.1/0.009 ≈ 11.1 Ω. Series R = V/I_g − G: for 10 V, 10000 − 100 = 9900 Ω; for 1 V, 1000 − 100 = 900 Ω.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-88","question":"Twelve identical resistors R form a 'wheel': six make the sides of a regular hexagon and six join each vertex to the centre. The equivalent resistance between two opposite vertices of the hexagon is:","options":["2R/3","3R/4","R","4R/5"],"answer":3,"explanation":"With A at potential V and the opposite vertex at 0, symmetry puts the centre at V/2 and gives the vertices next to A a common potential x, with the remaining two at V − x. Kirchhoff at a neighbour of A: (V − x) + (V − 2x) + (V/2 − x) = 0, so x = 5V/8. Current leaving A = 2(V − 5V/8)/R + (V/2)/R = 5V/(4R), so R_eq = 4R/5. Without the spokes it would be 1.5R; 3R/4 is the value between two vertices with one vertex between them.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-89","question":"A cell of emf 10 V and internal resistance 2 Ω is connected to a 6 Ω resistor in parallel with a variable resistor R. For the power dissipated in R itself to be maximum, R must be:","options":["1.5 Ω","2 Ω","3 Ω","6 Ω"],"answer":0,"explanation":"Replace the cell and the 6 Ω by their Thevenin equivalent as seen by R: R_th = 2 ∥ 6 = 1.5 Ω (E_th = 7.5 V). Maximum power in R needs R = R_th = 1.5 Ω. 3 Ω is the value that maximises power in the whole parallel combination, a different question.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-90","question":"Resistors of 2 Ω (temperature coefficient 0.004 per °C) and 3 Ω (temperature coefficient 0.001 per °C), both values at 0 °C, are connected in parallel. For small temperature changes, the temperature coefficient of the combination is about:","options":["0.0025 per °C","0.0028 per °C","0.0022 per °C","0.0050 per °C"],"answer":1,"explanation":"For parallel resistors 1/R = 1/R₁ + 1/R₂; differentiating gives α = (α₁R₂ + α₂R₁)/(R₁ + R₂) = (0.004 × 3 + 0.001 × 2)/5 = 0.0028 per °C. The series formula (α₁R₁ + α₂R₂)/(R₁ + R₂) gives the trap 0.0022.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-91","question":"A hollow metal cylinder of length L, inner radius a and outer radius b is made of material of resistivity ρ. The inner and outer curved surfaces are coated with perfect conductors and used as electrodes, so the current flows radially. The resistance between them is:","options":["ρL/[π(b² − a²)]","ρ ln(b/a)/(2πL)","ρ(b − a)/(2πaL)","ρ(b − a)/[π(a + b)L]"],"answer":1,"explanation":"A thin shell of radius r and thickness dr has resistance ρ dr/(2πrL). Adding these in series: R = (ρ/2πL)∫ₐᵇ dr/r = ρ ln(b/a)/(2πL). ρL/π(b² − a²) is the resistance for current along the axis, a different arrangement.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-92","question":"In a long cylindrical wire of radius R the current density varies with distance r from the axis as J = J₀(1 − r/R). The total current in the wire is:","options":["πJ₀R²/2","2πJ₀R²/3","πJ₀R²/3","πJ₀R²/6"],"answer":2,"explanation":"I = ∫₀ᴿ J₀(1 − r/R) 2πr dr = 2πJ₀(R²/2 − R²/3) = πJ₀R²/3. Multiplying the average of J over the radius (J₀/2) by the area gives the trap πJ₀R²/2; the outer rings have more area, where J is smaller.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-93","question":"An uncharged capacitor is charged through a resistor from a battery, the time constant of the circuit being τ. The rate at which energy is being stored in the capacitor is maximum at time:","options":["τ/2","2τ","τ","τ ln 2"],"answer":3,"explanation":"Power into the capacitor P = V_C i = (E²/R)(e^(−t/τ) − e^(−2t/τ)). dP/dt = 0 gives e^(−t/τ) = 1/2, so t = τ ln 2 ≈ 0.69τ; at that moment the capacitor holds half its final charge. The current, by contrast, is largest at t = 0.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-94","question":"A cell of emf 6 V (internal resistance 1 Ω) and a cell of emf 4 V (internal resistance 1 Ω) are connected in series with their positive terminals joined together, and the free terminals are connected through a 3 Ω resistor. The potential difference across the terminals of the 4 V cell is:","options":["4.4 V","4.0 V","3.6 V","1.2 V"],"answer":0,"explanation":"The emfs oppose: I = (6 − 4)/(1 + 1 + 3) = 0.4 A. This current is forced into the positive terminal of the 4 V cell, so it is being charged and its terminal voltage is E + Ir = 4 + 0.4 × 1 = 4.4 V. Using E − Ir = 3.6 V assumes it is discharging.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-95","question":"A capacitor C already charged to V/2 is connected, with the same polarity, through a resistor to a battery of emf V and left until charging stops. The fraction of the work done by the battery that is dissipated as heat in the resistor is:","options":["1/2","1/4","1/8","3/8"],"answer":1,"explanation":"Battery work = (extra charge) × V = C(V − V/2)V = CV²/2. Energy stored increases by (1/2)CV² − (1/2)C(V/2)² = 3CV²/8. Heat = CV²/2 − 3CV²/8 = CV²/8, which is 1/4 of the battery's work. The familiar 'half is lost' holds only for an initially uncharged capacitor.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-current-electricity-96","question":"The resistivity of a metal such as copper increases as its temperature rises mainly because:","options":["the metal expands, increasing its length","the number of free electrons decreases","the electrons gain mass","the free electrons collide more frequently with the more strongly vibrating ions"],"answer":3,"explanation":"ρ = m/(ne²τ). In a metal n hardly changes with temperature, but the lattice vibrations grow, shortening the mean time τ between collisions. Thermal expansion is a negligible effect.","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-current-electricity-97","question":"Kirchhoff's loop (voltage) rule — the sum of the potential changes round any closed loop is zero — is a consequence of the conservation of:","options":["momentum","charge","energy","mass"],"answer":2,"explanation":"Going round a closed loop, a charge returns to the same potential, so the net work done on it is zero. The loop rule expresses energy conservation (the junction rule expresses charge conservation).","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-current-electricity-98","question":"Six identical resistors R form the four sides and both diagonals of a square ABCD (the diagonals are not connected at their crossing). The equivalent resistance between two ADJACENT corners A and B is:","options":["R","R/2","2R/3","3R/4"],"answer":1,"explanation":"Every corner is connected to every other by one R, so all four corners are equivalent. Current from A to B: the direct R in parallel with the paths via C and via D. C and D are at the same potential (CD carries no current), so R_AB = R ∥ 2R ∥ 2R = R/2.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-current-electricity-99","question":"A 12 V battery of negligible internal resistance is connected to 2 Ω and 4 Ω resistors in series. A 3 μF capacitor is connected across the 4 Ω resistor. In the steady state, the charge on the capacitor is:","options":["24 μC","36 μC","12 μC","zero"],"answer":0,"explanation":"In the steady state no current flows into the capacitor, so the current is 12/6 = 2 A. The capacitor's voltage equals that across the 4 Ω resistor, 8 V, so Q = 3 × 8 = 24 μC.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-current-electricity-100","question":"A 10 V battery is connected across two parallel branches between points X (+) and Y. Branch 1: 2 Ω from X to P, then 3 Ω from P to Y. Branch 2: 2 μF from X to N, then 3 μF from N to Y (capacitors initially uncharged). In the steady state, the potential difference V_P − V_N is:","options":["2 V","−2 V","zero","6 V"],"answer":0,"explanation":"Resistor branch: V_P − V_Y = 10 × 3/5 = 6 V. Capacitor branch: series C = 1.2 μF, Q = 12 μC, so the 3 μF capacitor has 4 V: V_N − V_Y = 4 V. Hence V_P − V_N = 2 V (opposite to the resistor ratio, as capacitors divide voltage inversely).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-current-electricity-101","question":"An uncharged capacitor is charged through a resistor from a battery; the time constant is τ. The energy stored in the capacitor reaches one-quarter of its final value at time:","options":["τ/4","τ ln 4","τ ln(4/3)","τ ln 2"],"answer":3,"explanation":"U ∝ q², so U = U_max/4 when q = q_max/2. q = q_max(1 − e^(−t/τ)) = q_max/2 gives e^(−t/τ) = 1/2, so t = τ ln 2. (τ ln(4/3) is when the CHARGE is one-quarter.)","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-current-electricity-102","question":"A charged capacitor discharges through a resistor with time constant τ. The fraction of its initial energy that has been dissipated as heat after one time constant is about:","options":["0.37","0.63","0.86","0.14"],"answer":2,"explanation":"q = q₀e^(−t/τ), so U = U₀e^(−2t/τ). After t = τ, U = U₀/e² ≈ 0.135U₀. The energy dissipated is 1 − e⁻² ≈ 0.86 of the initial energy (0.63 is the fraction of CHARGE lost).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-current-electricity-103","question":"A tungsten filament lamp rated 100 W, 220 V operates with its filament about 2500 °C above room temperature. Taking the temperature coefficient of resistance of tungsten as 4.5 × 10⁻³ per °C (constant), the filament's resistance at room temperature is about:","options":["484 Ω","40 Ω","4.8 Ω","120 Ω"],"answer":1,"explanation":"Working resistance R = V²/P = 484 Ω. With R_hot = R_cold(1 + αΔT) = R_cold(1 + 11.25), R_cold = 484/12.25 ≈ 40 Ω. This is why a lamp draws a large surge of current at switch-on.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-current-electricity-104","question":"In a copper wire carrying a steady current, the drift speed of the free electrons is 0.1 mm/s. The time an individual electron takes to drift 1 m along the wire is about:","options":["10 seconds","2.8 hours","1 millisecond","1 minute"],"answer":1,"explanation":"t = 1 m/(10⁻⁴ m/s) = 10⁴ s ≈ 2.8 h. The lamp lights almost instantly because the electric field is set up along the wire at nearly the speed of light, starting all the electrons drifting at once.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-current-electricity-105","question":"Three branches are connected in parallel between points A and B: (i) a 10 V cell with internal resistance 2 Ω, (ii) a 4 V cell with internal resistance 2 Ω, both cells with their positive terminals towards A, and (iii) a 4 Ω resistor. The current through the 4 Ω resistor is:","options":["1.4 A","1.75 A","2.5 A","0.5 A"],"answer":0,"explanation":"Node potential (Millman): V_AB = (10/2 + 4/2 + 0/4)/(1/2 + 1/2 + 1/4) = 7/1.25 = 5.6 V. Current in the 4 Ω resistor = 5.6/4 = 1.4 A. (The 4 V cell is actually being charged, at 0.8 A.)","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-current-electricity-106","question":"A 2 μF capacitor is fully charged by a 10 V battery. The battery is then disconnected, turned round and reconnected through a resistor, so that the capacitor ends up charged with the opposite polarity. The heat produced in the resistor during this process is:","options":["zero","200 μJ","100 μJ","400 μJ"],"answer":3,"explanation":"The charge on the capacitor changes from +20 μC to −20 μC, so 40 μC passes through the battery, which does 40 μC × 10 V = 400 μJ of work. The stored energy is 100 μJ both before and after, so all 400 μJ becomes heat.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-current-electricity-107","question":"A conductor of resistivity ρ has the shape of a frustum of a cone of length L, with end radii a and b. Assuming the current is uniform over each cross-section, its resistance between the flat ends is:","options":["2ρL/[π(a² + b²)]","ρL/(πa²)","ρL/(πab)","ρL/[π((a + b)/2)²]"],"answer":2,"explanation":"The radius varies linearly: r(x) = a + (b − a)x/L. R = ∫ρ dx/(πr²) = (ρ/π)(L/(b − a))[1/a − 1/b] = ρL/(πab). Using the average radius or average area gives a different (wrong) result.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-current-electricity-108","question":"The space between two concentric thin metal spherical shells of radii a and b (b > a) is filled with a material of resistivity ρ. The resistance between the shells is:","options":["ρ ln(b/a)/(4π)","ρ(b − a)/(4πa²)","ρ(b − a)/(4πab)","ρ(b − a)/[4π(b² − a²)]"],"answer":2,"explanation":"Current flows radially through thin shells of area 4πr²: R = ∫ₐᵇ ρ dr/(4πr²) = (ρ/4π)(1/a − 1/b) = ρ(b − a)/(4πab).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-current-electricity-109","question":"Twenty-four identical cells, each of emf 2 V and internal resistance 1 Ω, are to be arranged in a mixed grouping (equal series rows connected in parallel) to send the maximum current through an external 6 Ω resistor. The maximum current is:","options":["4 A","2 A","1.6 A","8 A"],"answer":1,"explanation":"With n cells in series in each of m rows (nm = 24): I = 2n/(6 + n/m). The current is maximum when the internal resistance n/m equals 6 Ω: n²/24 = 6, so n = 12, m = 2. Then I = 24/(6 + 6) = 2 A.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-current-electricity-110","question":"Five identical resistors R form the four sides of a square ABCD and its diagonal AC. The equivalent resistance between B and D is:","options":["R","R/2","2R/3","5R/8"],"answer":0,"explanation":"By symmetry about the line BD, corners A and C are at the same potential when current enters at B and leaves at D, so the diagonal AC carries no current. What remains is two paths B–A–D and B–C–D, each 2R, in parallel: R_BD = R.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-current-electricity-111","question":"A copper wire and an iron wire of the same length and the same cross-section are joined end to end and carry a steady current. Iron's resistivity is about six times that of copper. The electric field inside the iron is:","options":["zero, as in electrostatics","equal to that inside the copper","about one-sixth of that inside the copper","about six times that inside the copper"],"answer":3,"explanation":"The same current density J flows in both (same current, same area), and E = ρJ. So the field is proportional to the resistivity, about six times larger in the iron. A steady current needs a non-zero field inside the conductor.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-current-electricity-112","question":"A 12 V battery (no internal resistance) is connected through a 6 Ω resistor to a 3 Ω resistor; an initially uncharged 2 μF capacitor is connected across the 3 Ω resistor and the switch is closed at t = 0. The time constant of the charging and the final charge on the capacitor are:","options":["6 μs and 24 μC","18 μs and 8 μC","4 μs and 24 μC","4 μs and 8 μC"],"answer":3,"explanation":"Seen from the capacitor, the circuit is a Thevenin source: V_th = 12 × 3/9 = 4 V and R_th = 6 ∥ 3 = 2 Ω. So τ = R_th C = 4 μs and Q_final = CV_th = 8 μC.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-current-electricity-113","question":"To measure a small resistance (about 1 Ω) with an ammeter of resistance 0.5 Ω and a voltmeter of resistance 10 kΩ, the better arrangement is:","options":["voltmeter in series with the resistor","ammeter in series with the resistor, and the voltmeter across both","voltmeter connected directly across the resistor, with the ammeter outside this combination","either arrangement gives the same accuracy"],"answer":2,"explanation":"With the voltmeter directly across R, the only error is the tiny current (≈ 10⁻⁴ of the total) drawn by the voltmeter. With the voltmeter across both R and the ammeter, it would include the ammeter's 0.5 Ω, a 50% error for a 1 Ω resistor.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-current-electricity-114","question":"Two wires of the same material, one of length l and radius r and the other of length 2l and radius 2r, are connected in parallel across a battery. The ratio of the heat produced per second in the first wire to that in the second is:","options":["2 : 1","1 : 2","1 : 4","1 : 1"],"answer":1,"explanation":"R ∝ l/r²: R₁ ∝ l/r² and R₂ ∝ 2l/(4r²) = R₁/2. In parallel the voltage is common, so P = V²/R and P₁ : P₂ = R₂ : R₁ = 1 : 2.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-current-electricity-115","question":"In a network, AB = 2 Ω, BC = 4 Ω, AD = 4 Ω, DC = 2 Ω and BD = 4 Ω. A 12 V battery of negligible internal resistance is connected between A (+) and C. The current in BD is:","options":["0.6 A, from B to D","0.6 A, from D to B","zero, since the bridge is balanced","1.2 A, from B to D"],"answer":0,"explanation":"The bridge is not balanced (2/4 ≠ 4/2). Nodal analysis with V_A = 12 V, V_C = 0: for B, (12 − V_B)/2 = V_B/4 + (V_B − V_D)/4; for D, (12 − V_D)/4 = V_D/2 + (V_D − V_B)/4. These give V_B = 7.2 V and V_D = 4.8 V, so 2.4/4 = 0.6 A flows from B to D.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-current-electricity-116","question":"A 12 V battery of internal resistance 2 Ω has a fixed 6 Ω resistor connected permanently across its terminals. A variable load resistor is also connected across the terminals. The maximum power that can be delivered to the load is:","options":["13.5 W","18 W","12 W","9 W"],"answer":0,"explanation":"Replace the battery and 6 Ω by their Thevenin equivalent: V_th = 12 × 6/8 = 9 V and R_th = 2 ∥ 6 = 1.5 Ω. Maximum power occurs when R_load = 1.5 Ω: P = V_th²/(4R_th) = 81/6 = 13.5 W.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-current-electricity-117","question":"Two wires of the same material and the same mass have lengths in the ratio 2 : 1. The ratio of their resistances is:","options":["1 : 1","2 : 1","8 : 1","4 : 1"],"answer":3,"explanation":"Same mass and density means the same volume: A = V/L. So R = ρL/A = ρL²/V ∝ L², giving 2² : 1 = 4 : 1.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-current-electricity-118","question":"The current through a wire decays as I = I₀e^(−t/τ) with I₀ = 2 A and τ = 5 s. The total charge that flows through the wire from t = 0 onwards is:","options":["6.3 C","2.5 C","10 C","infinite"],"answer":2,"explanation":"Q = ∫₀^∞ I₀e^(−t/τ) dt = I₀τ = 2 × 5 = 10 C. (About 63% of it, 6.3 C, passes in the first time constant.)","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-current-electricity-119","question":"A uniform wire of total resistance 12 Ω is bent into a circle, and an ideal 6 V cell is inserted into the circle at one point (in series with the wire). The potential difference between the positive terminal of the cell and the point of the wire diametrically opposite to it is:","options":["6 V","3 V","zero","1.5 V"],"answer":1,"explanation":"The whole ring is one series loop: I = 6/12 = 0.5 A. Going round from the positive terminal, half the ring (6 Ω) lies before the opposite point, so the potential falls by 0.5 × 6 = 3 V.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-current-electricity-120","question":"A lamp rated 6 V, 3 W is to be run at its rated power from a 9 V battery of negligible internal resistance. The resistance that must be connected in series with it is:","options":["12 Ω","6 Ω","3 Ω","18 Ω"],"answer":1,"explanation":"Rated current I = P/V = 0.5 A. The series resistor must drop 9 − 6 = 3 V at 0.5 A, so R = 6 Ω (dissipating 1.5 W).","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-current-electricity-121","question":"A 12 V battery of negligible internal resistance is connected through a switch to a 4 Ω resistor in series with a parallel combination of a 12 Ω resistor and an uncharged capacitor. Just after the switch is closed, the current from the battery is:","options":["3 A","0.75 A","1 A","zero"],"answer":0,"explanation":"An uncharged capacitor has no voltage across it at first, so it acts like a short circuit across the 12 Ω resistor. The initial current is 12/4 = 3 A; it decays to the steady value 12/16 = 0.75 A as the capacitor charges.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-current-electricity-122","question":"Two copper wires of radii r and 2r are joined end to end and carry a steady current. The ratio of the drift speed of electrons in the thinner wire to that in the thicker wire is:","options":["1 : 1","2 : 1","1 : 4","4 : 1"],"answer":3,"explanation":"I = neAv_d is the same in both wires and n is the same (same metal), so v_d ∝ 1/A ∝ 1/r². The ratio is (2r)²/r² = 4 : 1.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-current-electricity-123","question":"A copper wire (resistivity 1.7 × 10⁻⁸ Ω m) carries a current density of 1 × 10⁶ A/m². The electric field inside the wire is:","options":["17 V/m","1.7 V/m","0.017 V/m","1.7 × 10⁻¹⁴ V/m"],"answer":2,"explanation":"Ohm's law in microscopic form: E = ρJ = 1.7 × 10⁻⁸ × 10⁶ = 1.7 × 10⁻² V/m. Even a large current density needs only a small field in a good conductor.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-current-electricity-124","question":"A Wheatstone bridge is balanced, with the galvanometer showing no deflection. The battery and the galvanometer are now interchanged (each moved to the other's diagonal). The galvanometer will:","options":["show a deflection in the same sense","show a deflection in the opposite sense","still show no deflection","show a deflection that depends on the battery's emf"],"answer":2,"explanation":"Balance requires P/Q = R/S. After interchange the new balance condition is P/R = Q/S, which is the same equation rearranged. So the bridge stays balanced (a consequence of the reciprocity theorem).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-current-electricity-125","question":"A charged capacitor is discharged through resistors of 2 Ω and 3 Ω connected in parallel. The ratio of the total heat produced in the 2 Ω resistor to that in the 3 Ω resistor is:","options":["2 : 3","3 : 2","1 : 1","9 : 4"],"answer":1,"explanation":"At every instant both resistors have the same voltage, so the power ratio is (1/2) : (1/3) = 3 : 2. Integrating over the whole discharge, the heats are in the same ratio, 3 : 2.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-current-electricity-126","question":"A 2 kW room heater is used for 3 hours a day. If electricity costs ₹5 per kWh, the cost of running it for 10 days is:","options":["₹300","₹30","₹600","₹150"],"answer":0,"explanation":"Energy per day = 2 kW × 3 h = 6 kWh, costing ₹30. Over 10 days that is 60 kWh, i.e. ₹300.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-current-electricity-127","question":"Copper has about 8.5 × 10²⁸ free electrons per m³ and resistivity 1.7 × 10⁻⁸ Ω m. Taking the electron mass as 9.1 × 10⁻³¹ kg and e = 1.6 × 10⁻¹⁹ C, the average time between collisions (relaxation time) is about:","options":["2.5 × 10⁻¹⁸ s","2.5 × 10⁻¹⁰ s","4 × 10⁻¹³ s","2.5 × 10⁻¹⁴ s"],"answer":3,"explanation":"From ρ = m/(ne²τ): τ = m/(ne²ρ) = 9.1 × 10⁻³¹/(8.5 × 10²⁸ × 2.56 × 10⁻³⁸ × 1.7 × 10⁻⁸) ≈ 2.5 × 10⁻¹⁴ s.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-current-electricity-128","question":"A ladder network has three identical series resistors R along the top (A to P₁, P₁ to P₂, P₂ to P₃) and three identical shunt resistors R from P₁, P₂ and P₃ to a common bottom line. The equivalent resistance between A and the bottom line is:","options":["8R/5","3R/2","5R/3","13R/8"],"answer":3,"explanation":"Work back from the far end: at P₃ the shunt R; at P₂, R ∥ (R + R) = 2R/3; at P₁, R ∥ (R + 2R/3) = R ∥ 5R/3 = 5R/8. Adding the first series R gives 13R/8. (The infinite ladder would give (1 + √5)R/2 ≈ 1.618R.)","difficulty":"very-hard","source":"JEE Advanced pattern"},
];

export default questions;
